// Basic REST api backend for testing

import { Leads } from "@/lib/types";

// Test mock report json that gets sent to the client. This will be generated by an sql query based on the actual leads data.
const mockReport: Leads.Report = {
  fiscalYear: undefined,
  donorType: undefined,
  pipelineStage: undefined,
  fiscalYearOptions: [
    { key: "fy-2025", label: "FY 2025" },
    { key: "fy-2026", label: "FY 2026" },
  ],
  donorTypeOptions: [
    { key: "donor-type-one", label: "Donor Type One" },
    { key: "donor-type-two", label: "Donor Type Two" },
    { key: "donor-type-three", label: "Donor Type Three" },
    { key: "donor-type-four", label: "Donor Type Four" },
  ],
  pipelineStageOptions: [
    { key: "stage-one", label: "Stage One" },
    { key: "stage-two", label: "Stage Two" },
  ],
  quarterlySummary: {
    headers: ["Q1", "Q2", "Q3", "Q4", "fy-2025"],
    coreMonetaryValue: {
      totalEstimatedValuation: [0, 0, 0, 0, 0],
      probabilityAdjustedValue: [0, 0, 0, 0, 0],
      securedValue: [0, 0, 0, 0, 0],
      unsecuredBalance: [0, 0, 0, 0, 0],
    },
    conversionEfficiencyAndRatios: {
      donorConversionRate: [0, 0, 0, 0, 0],
      valueRealizationRate: [0, 0, 0, 0, 0],
    },
    leadOriginBreakdown: {
      referral: [0, 0, 0, 0, 0],
      research: [0, 0, 0, 0, 0],
      booths: [0, 0, 0, 0, 0],
      callOrText: [0, 0, 0, 0, 0],
      walkIn: [0, 0, 0, 0, 0],
      subTotalLeadIntake: [0, 0, 0, 0, 0],
    },
    pipelineStageBreakdown: {
      newLead: [0, 0, 0, 0, 0],
      underResearch: [0, 0, 0, 0, 0],
      outreachStarted: [0, 0, 0, 0, 0],
      proposalSent: [0, 0, 0, 0, 0],
      securedDonor: [0, 0, 0, 0, 0],
      subTotalProspectRecords: [0, 0, 0, 0, 0],
    },
  },
};

export async function GET(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    
    const donorType = searchParams.get("donorType") ?? undefined;
    const fiscalYear = searchParams.get("fiscalYear") ?? undefined;
    const pipelineStage = searchParams.get("pipelineStage") ?? undefined;

    mockReport.timestamp = new Date().toISOString();

    mockReport.donorType = donorType;
    mockReport.fiscalYear = fiscalYear;
    mockReport.pipelineStage = pipelineStage;

    mockReport.quarterlySummary!.headers![4] =
      mockReport.fiscalYearOptions?.find(
        (option) => option.key === mockReport.fiscalYear,
      )?.label ?? "—";

    console.log(
      `[GET] Lead pipeline report filters: ${donorType}, ${fiscalYear}, ${pipelineStage}`,
    );

    return Response.json(mockReport);
  } catch (err) {
    const message = err instanceof Error ? err.message : "Unknown error";
    return Response.json({ error: message }, { status: 500 });
  }
}
